export type OutgoingBrandId = 'visa' | 'elo' | 'mastercard';

export type PresenceStatus = 'Obrigatório' | 'Condicional' | 'Opcional';
export type FieldStatus = 'M' | 'C' | 'O';

export interface OutgoingFieldSpec {
  fieldNo: string;
  name: string;
  pos: string;
  size: string;
  format: string;
  status: FieldStatus;
  conditionRule: string;
  description: string;
  example: string;
  failureImpact: string;
}

export interface OutgoingContentBlock {
  title: string;
  badge: string;
  summary: string;
  keyFields: string[];
}

export interface OutgoingTableSpec {
  id: string;
  brand: OutgoingBrandId;
  code: string;
  shortCode: string;
  title: string;
  subtitle: string;
  category:
    | 'Envelope de Arquivo'
    | 'Base Financeira Obrigatória'
    | 'Liquidação Nacional Brasil'
    | 'Segurança, EMV & 3DS'
    | 'Modalidades & Subcredenciadores'
    | 'Setorial & Companhias Aéreas'
    | 'Pós-Venda, Disputas & Retorno';
  direction: '▶ Envia (Credenciador → Bandeira)' | '◀ Recebe (Bandeira → Credenciador)' | '⇄ Ambos (Remessa & Retorno)';
  sizeSpec: string;
  presenceStatus: PresenceStatus;
  presenceSummary: string;
  whatItIs: string;
  whenMandatory: string[];
  whenConditionalOrNotUsed: string[];
  whatItContains: OutgoingContentBlock[];
  sourceRef: {
    manual: string;
    version: string;
    effectiveDate: string;
    pages: string;
  };
  fields: OutgoingFieldSpec[];
}

export interface FlowRecordStep {
  order: number;
  tableId: string;
  tableCode: string;
  tableName: string;
  statusInFlow: 'Obrigatório no Fluxo' | 'Condicional no Fluxo' | 'Envelope do Lote';
  roleInFlow: string;
  keyValuesInFlow: string[];
}

export interface AuthToClearingMap {
  authField: string;
  outgoingTable: string;
  outgoingField: string;
  rule: string;
}

export interface FlowMandatoryEscalation {
  target: string;
  generalStatus: 'Condicional (C)';
  statusInThisFlow: 'Obrigatório (M)';
  triggerCondition: string;
  consequenceIfMissing: string;
}

export interface OutgoingBrandFlow {
  summary: string;
  architectureNote: string;
  brazilSpecificRule: string;
  recordSequence: FlowRecordStep[];
  authToClearingDePara: AuthToClearingMap[];
  conditionalTurnedMandatory: FlowMandatoryEscalation[];
}

export interface OutgoingFlowSpec {
  id: string;
  number: string;
  title: string;
  subtitle: string;
  tag: string;
  byBrand: Record<OutgoingBrandId, OutgoingBrandFlow>;
}

export interface OutgoingMatrixRow {
  tableId: string;
  tableCode: string;
  tableName: string;
  generalStatus: PresenceStatus;
  cells: Record<
    string,
    {
      status: 'M' | 'C' | 'O' | '-';
      note: string;
    }
  >;
}

export interface OutgoingBrandMeta {
  id: OutgoingBrandId;
  name: string;
  badge: string;
  accentColor: string;
  manualTitle: string;
  version: string;
  effectiveDate: string;
  physicalFormat: string;
  hierarchyFormula: string;
  dailyWindows: {
    label: string;
    windowTime: string;
    scope: string;
  }[];
  overviewSummary: string;
}

