        title: 'Chave de Ciclo de Vida (TID + Validation Code)',
        badge: 'Pos 5–40',
        summary: 'Transaction Identifier de 15 dígitos (pos 5–19), Valor e Moeda Autorizados (pos 20–34), Response Code "00" (pos 35–36) e Validation Code de 4 posições (pos 37–40).',
